    print(f"{col}:", dbcore.check_values(con,'source_value_extractions',col) or "(no CHECK)")
print("\n--- REF-00995 / REF-00996 extractions (the rise-conditioned analogue) ---")
for r in con.execute("""select extraction_id,ref_id,claim_type,claimed_value,claimed_unit,comparator,figure_role,
