    print(" ", dict(r))
print("\n--- extraction_relations shape ---")
print("cols:", ", ".join(c[1] for c in con.execute('PRAGMA table_info(extraction_relations)')))
for r in con.execute("select * from extraction_relations limit 4"): print("  ", dict(r))
PY

